UPDATE articulos 
SET metadata = '{"areas": ["creatividad", "sociabilidad", "carácter"], "lugares": ["Interior", "Exterior"], "cantidad": "04 participantes", "duracion": "25 minutos", "unidades": ["manada", "compañía", "tropa"], "objetivos": ["Estimular la creatividad", "Fomentar la comunicación e interpretación", "Estímulo y desarrollo de la memoria", "Trabajo en equipo"], "materiales": ["Manta", "Objetos Varios", "Pañolines"], "variaciones": "<b>Relato por Cuerdas y Claves:</b> Utilizar exclusivamente herramientas técnicas de campamento (nudos, brújulas, estacas) exigiendo que el uso del objeto en la historia esté vinculado a una función técnica scout.<br><b>El Telón Sonoro:</b> En lugar de objetos visuales, emitir un sonido oculto detrás del telón (ej. choque de piedras, chasquido de ramas) que el participante debe incorporar a la narración.<br><b>Cadena de Objetos Acumulativos:</b> A medida que avanza el juego, el scout debe recordar y nombrar todos los objetos presentados previamente en orden cronológico.", "recomendaciones": "Mantener una bolsa o caja con objetos variados y curiosos fuera de la vista del grupo para acelerar la rotación del juego. Fomentar un ambiente positivo donde todas las ideas imaginarias sean celebradas sin juzgar ni interrumpir la intervención del compañero. Adaptar la complejidad de los objetos y la temática según la edad de la unidad.", "justificacion_areas": "El Telón de los Objetos Mágicos potencia la creatividad al requerir la asociación simbólica instantánea e improvisación narrativa a partir de estímulos visuales. Fortalece la sociabilidad al ejercitar la escucha activa, la colaboración sinérgica y la construcción colectiva de significados en el grupo. Desarrolla el carácter al entrenar la confianza personal al hablar en público y la capacidad de superar la inhibición inicial.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "texto": "Me gusta participar en juegos de observación.", "unidad": "Manada", "como_se_cumple": "Observando rápidamente las características del objeto revelado para inspirar la historia."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "unidad": "Manada", "como_se_cumple": "Demostrando rapidez mental e imaginación al vincular el objeto misterioso con la trama."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "texto": "Doy mi opinión sobre las cosas que me pasan.", "unidad": "Compañía", "como_se_cumple": "Expresando ideas y giros narrativos originales con fluidez e iniciativa en la patrulla."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "unidad": "Compañía", "como_se_cumple": "Conectando creativamente los elementos dispares aportados por los compañeros en una sola historia."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "texto": "Doy mi opinión sobre las cosas que me pasan.", "unidad": "Tropa", "como_se_cumple": "Participando con soltura y agilidad de pensamiento en el desarrollo de la trama de la Tropa."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "unidad": "Tropa", "como_se_cumple": "Analizando las múltiples posibilidades simbólicas del objeto para resolver la narración de grupo."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "unidad": "Manada", "como_se_cumple": "Respetando con disciplina el turno de palabra y la inmovilidad al dar la espalda."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "unidad": "Manada", "como_se_cumple": "Escuchando con atención la intervención del compañero antes de continuar la historia."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Compañía", "como_se_cumple": "Promoviendo el respeto por el relato ajeno y la construcción colaborativa sin interrupciones."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Compañía", "como_se_cumple": "Cumpliendo con honestidad las reglas del juego y enriqueciendo el trabajo en equipo."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Tropa", "como_se_cumple": "Acatando las indicaciones de partida y respetando las ideas creativas de la patrulla."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Tropa", "como_se_cumple": "Fomentando la sana convivencia y la cohesión del grupo mediante el humor y la empatía."}, {"id": "041daaea-c4a7-472b-a613-951bd25cfa85", "area": "Carácter", "texto": "Reconozco y acepto mis errores.", "unidad": "Manada", "como_se_cumple": "Aceptando con serenidad las pausas o titubeos al hablar ante el grupo y corrigiendo sobre la marcha."}, {"id": "4df1ba93-06fe-4f49-b273-fddc3800cf17", "area": "Carácter", "texto": "Le doy importancia a las cosas que hago bien.", "unidad": "Manada", "como_se_cumple": "Valorando el propio aporte creativo en la construcción de la historia colectiva."}, {"id": "2cc128e0-7cc6-49df-a7c5-825f6ab79793", "area": "Carácter", "texto": "Sé que puedo ser cada día mejor.", "unidad": "Compañía", "como_se_cumple": "Superando la timidez inicial y expresándose con mayor desenvoltura en cada turno."}, {"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "area": "Carácter", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "unidad": "Compañía", "como_se_cumple": "Confiando en las propias habilidades de comunicación y expresión ante sus pares."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "area": "Carácter", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "unidad": "Tropa", "como_se_cumple": "Descubriendo nuevas capacidades de improvisación e invención en el ámbito público."}, {"id": "78bd48d3-5d26-4218-843a-33712bade630", "area": "Carácter", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "unidad": "Tropa", "como_se_cumple": "Demostrando autodominio y seguridad al conducir la trama de la historia con carisma."}]}'::jsonb, updated_at = NOW() 
